      PLATFORM_X_CLIENT_ID:'fixture-x-client', PLATFORM_X_CLIENT_SECRET:'fixture-x-secret', PLATFORM_X_REDIRECT_URI:`${base}/api/platform/x/callback`,
      PLATFORM_AUTH_EMAIL_ENABLED:'1',PLATFORM_PUBLIC_SIGNUP_ENABLED:'1',PLATFORM_AUTH_ORIGIN:base,PLATFORM_AUTH_FROM_EMAIL:'accounts@ryzevo.example',PLATFORM_AUTH_SES_REGION:'eu-west-1',PLATFORM_AUTH_SES_ACCESS_KEY_ID:'AKIA'+'A'.repeat(16),PLATFORM_AUTH_SES_SECRET_ACCESS_KEY:'b'.repeat(40),
      PLATFORM_PAYTR_SANDBOX_ENABLED:'0',PLATFORM_PAYTR_MERCHANT_ID:'123456',PLATFORM_PAYTR_MERCHANT_KEY:'http-fixture-key-1234',PLATFORM_PAYTR_MERCHANT_SALT:'http-fixture-salt-1234',PLATFORM_PAYTR_TEST_CATALOG:'[]',
