    const mobileSave=await request('/api/platform/mobile',mobileOwner,'POST',{action:'saveApp',name:'HTTP QA Mobile',platform:'both',appleId:'123456789',bundleId:'com.mobile.qa',packageName:'com.mobile.qa',country:'TR',locale:'tr-TR',website:'https://mobile.example',scheme:'qaapp',attributionProvider:'bridge',revenueProvider:'bridge',identityConfirmed:false});assert.equal(mobileSave.status,200);const mobileApp=await mobileSave.json();
    assert.equal((await request('/api/platform/mobile?appId='+mobileApp.id,beta)).status,404);
