    assert.equal((await request('/api/platform/mobile',mobileOwner,'POST',{action:'source',appId:mobileApp.id,enabled:true})).status,200);
    assert.equal((await request('/api/platform/mobile',mobileOwner,'POST',{action:'saveIntegration',appId:mobileApp.id,provider:'bridge',credentials:{webhookSecret:'http-fixture-secret-'.repeat(3)}})).status,200);
    const mobileView=await (await request('/api/platform/mobile?appId='+mobileApp.id,mobileOwner)).json(),mobileConnection=mobileView.integrations[0];assert.equal(mobileView.sendEnabled,false);assert.equal(mobileView.report.installs,null);assert.doesNotMatch(JSON.stringify(mobileView),/http-fixture-secret|encrypted_|private_key/);
    const hookRequest=body=>fetch(`${base}${mobileConnection.endpoint}`,{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+'http-fixture-secret-'.repeat(3)},body:JSON.stringify(body)});
    assert.equal((await hookRequest({appId:mobileApp.id,events:[{id:'http-install',entityId:'http-user1',kind:'install',occurredAt:new Date().toISOString()}]})).status,200);
    assert.equal((await hookRequest({action:'register',appId:mobileApp.id,entityId:'http-user1',provider:'bridge',recordedAt:new Date().toISOString(),evidenceRef:'qa/http-opt-in',consent:{push:false,inApp:true}})).status,200);
    assert.equal((await hookRequest({action:'feed',appId:mobileApp.id,entityId:'http-user1'})).status,200);
    assert.equal((await request('/api/platform/plan',admin)).status,403);
    assert.equal((await request('/api/platform/billing',admin)).status,403);
