    const alphaPlanResponse=await request(`/api/platform/plan?organizationId=${b.organizationId}&projectId=${b.projectId}`,alpha);assert.equal(alphaPlanResponse.status,200);assert.match(alphaPlanResponse.headers.get('cache-control'),/private.*no-store/);
