    assert.equal((await request('/api/platform/plan',alpha,'POST',{planId:'enterprise',paid:true,limit:99999})).status,400);
    assert.equal((await fetch(`${base}/api/platform/plan`,{method:'POST',headers:{Cookie:alpha,'Content-Type':'application/json',Origin:'https://evil.example'},body:JSON.stringify({planId:'launch',catalogVersion:alphaPlan.commercial.catalogVersion})})).status,403);
    const preferred=await request('/api/platform/plan',alpha,'POST',{planId:'growth',catalogVersion:alphaPlan.commercial.catalogVersion});assert.equal(preferred.status,200);const preference=await preferred.json();assert.equal(preference.commercial.preference.planId,'growth');assert.equal(preference.plan.id,'pilot');assert.equal(preference.resources.find(r=>r.resource==='ai').limit,50);
    const betaPlan=await (await request('/api/platform/plan',beta)).json();assert.equal(betaPlan.projectId,b.projectId);assert.equal(betaPlan.commercial.preference,null);
