      assert.equal((await request('/api/auth/identity','','POST',{action:'inspect',kind:'verify',token:mail.token})).status,200);
      assert.equal((await request('/api/auth/identity','','POST',{action:'verify',token:mail.token})).status,200);
      assert.equal((await request('/api/auth/identity','','POST',{action:'verify',token:mail.token})).status,400);
